// DefaultIPValidator defines the struct for the default IPValidator.
type DefaultIPValidator struct {
	netClient networkutils.NetClient
}

// IPValidator defines an interface for the methods to validate the control plane IP.
type IPValidator interface {
	ValidateControlPlaneIPUniqueness(cluster v1alpha1.ClusterSpec) error
}

// NewIPValidator initializes a new IPValidator object.
func NewIPValidator(netClient ...networkutils.NetClient) IPValidator {
	client := networkutils.NetClient(&networkutils.DefaultNetClient{})
	if len(netClient) > 0 && netClient[0] != nil {
		client = netClient[0]
	}
	return DefaultIPValidator{netClient: client}
}

func (v DefaultIPValidator) ValidateControlPlaneIPUniqueness(spec v1alpha1.ClusterSpec) error {
	netClient := v.netClient
	if netClient == nil {
		netClient = &networkutils.DefaultNetClient{}
	}

